-- Banco adicional compartido. No modifica evaluaciones, progreso ni calificaciones.
CREATE TABLE IF NOT EXISTS evaluacion_banco_repaso (
 id CHAR(36) PRIMARY KEY, grado INT NOT NULL, curso VARCHAR(32) NOT NULL,
 orden INT NOT NULL, tema VARCHAR(120) NOT NULL, enunciado TEXT NOT NULL,
 opcion_1 TEXT NOT NULL, opcion_2 TEXT NOT NULL, opcion_3 TEXT NOT NULL,
 correcta INT NOT NULL, explicacion TEXT NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE,
 INDEX idx_repaso_curso_grado(curso,grado,activo)
) CHARACTER SET utf8mb4;
UPDATE evaluacion_banco_repaso SET opcion_3='2' WHERE id='9a185574-8c21-56ca-8e44-27bcf3d81779' AND opcion_1='4' AND opcion_2='3' AND opcion_3='3';
